from pptx import Presentation
from pptx.util import Pt, Emu

prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')
slide_width = prs.slide_width
slide_height = prs.slide_height

print(f"Total slides: {len(prs.slides)}")
print(f"Slide dims: {slide_width} x {slide_height} EMU")
print("=" * 100)

for slide_idx, slide in enumerate(prs.slides):
    print(f"\n--- Slide {slide_idx + 1} ---")
    for shape in slide.shapes:
        is_ph = shape.is_placeholder
        if not is_ph and shape.shape_type == 17 and shape.has_text_frame:
            text = shape.text_frame.text.strip()
            print(f"  Paper title TextBox: '{text}'")
            print(f"    left={shape.left}, top={shape.top}, w={shape.width}, h={shape.height}")
            print(f"    left_in={shape.left/914400:.2f}, top_in={shape.top/914400:.2f}")
            centered = abs(shape.left - (slide_width - shape.width) // 2) < 100
            print(f"    Horizontally centered: {centered}")
            bottom_gap = slide_height - shape.top - shape.height
            print(f"    Bottom gap: {bottom_gap} EMU = {bottom_gap/914400:.2f} inches")
            for para in shape.text_frame.paragraphs:
                for run in para.runs:
                    print(f"    Font: name={run.font.name}, size={run.font.size}, bold={run.font.bold}, color={run.font.color.rgb}")

        if is_ph:
            try:
                ph_type = shape.placeholder_format.type
                ph_idx = shape.placeholder_format.idx
                if shape.has_text_frame:
                    text = shape.text_frame.text.strip()[:100]
                    if text:
                        print(f"  Placeholder {ph_idx} ({ph_type}): '{text}'")
            except:
                pass

# Check last slide (Reference)
print("\n=== Reference Slide (Last) ===")
last_slide = prs.slides[len(prs.slides) - 1]
for shape in last_slide.shapes:
    if shape.has_text_frame:
        print(f"  Shape '{shape.name}':")
        for para in shape.text_frame.paragraphs:
            if para.text.strip():
                print(f"    '{para.text.strip()}'")
